pub fn reverse(v: &mut Vec<u64>) {
    let n = v.len();
    // For n == 0 or n == 1, the loop runs 0 times (no-op).
    for i in 0..(n / 2) {
        let j = n - 1 - i;
        v.swap(i, j);
    }
}

